<?php declare(strict_types=1); ?>
<div class="page-wrap financial-report"><a href="<?= pl_e(pl_url('/reports')) ?>" class="back-link"><?= pl_icon('arrow-left') ?> All reports</a><div class="page-heading"><div><p class="eyebrow">How the business is performing</p><h1>Profit & loss</h1><p class="muted"><?= pl_e($company['name']) ?> · <?= pl_e(pl_date_label($from)) ?> to <?= pl_e(pl_date_label($to)) ?></p></div><form method="get" action="<?= pl_e(pl_url('/reports/profit-loss')) ?>" class="report-filter period-filter"><label class="field">From<input type="date" name="from" value="<?= pl_e($from) ?>" required></label><label class="field">To<input type="date" name="to" value="<?= pl_e($to) ?>" required></label><button class="button secondary">Update</button><a class="button secondary" href="<?= pl_e(pl_url('/reports/export', ['report' => 'profit-loss', 'from' => $from, 'to' => $to])) ?>">Export CSV</a></form></div>
<div class="report-kpis"><div><span>Income</span><strong><?= pl_e($company['currency'] . ' ' . pl_money($report['total_income'])) ?></strong></div><div><span>Expenses</span><strong><?= pl_e($company['currency'] . ' ' . pl_money($report['total_expenses'])) ?></strong></div><div class="emphasized"><span><?= bccomp($report['net_profit'], '0', 4) < 0 ? 'Net loss' : 'Net profit' ?></span><strong><?= pl_e($company['currency'] . ' ' . pl_money($report['net_profit'])) ?></strong></div></div>
<div class="statement-columns two-columns"><?php foreach (['income' => 'Income', 'expenses' => 'Expenses'] as $key => $label): ?><section class="panel"><h2><?= pl_e($label) ?></h2><div class="table-wrap"><table class="data-table statement-table"><caption class="sr-only"><?= pl_e($label . ' in ' . $company['currency']) ?></caption><tbody><?php foreach ($report[$key] as $row): ?><tr><th scope="row"><a href="<?= pl_e(pl_url('/reports/account', ['id' => $row['id'], 'as_of' => $to, 'from' => $from])) ?>"><span class="account-code"><?= pl_e($row['code']) ?></span><?= pl_e($row['name']) ?></a></th><td class="amount"><?= pl_e(pl_money($row['amount'])) ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><th scope="row">Total <?= pl_e(strtolower($label)) ?></th><td class="amount"><?= pl_e(pl_money($report['total_' . $key])) ?></td></tr></tfoot></table></div></section><?php endforeach; ?></div>
<div class="profit-equation"><span>Income</span><strong><?= pl_e(pl_money($report['total_income'])) ?></strong><span>− Expenses</span><strong><?= pl_e(pl_money($report['total_expenses'])) ?></strong><span>= Net profit / loss</span><strong><?= pl_e(pl_money($report['net_profit'])) ?></strong></div><p class="small muted">The selected period includes posted entries and dated reversals. Profit differs from cash: this statement follows account classifications, while the balance sheet shows cash, other assets and liabilities.</p></div>
